function detectAffiliateSource(rawUrl:string){
 try{
  const u=new URL(rawUrl); const host=u.hostname.replace(/^www\./,"").toLowerCase();
  if(host==="amzn.to"||host.startsWith("amazon.")) return {merchant:"Amazon",network:"Amazon Associates",productType:"amazon_affiliate" as ProductType};
  if(host.includes("walmart.")) return {merchant:"Walmart",network:"Impact",productType:"dropshipping" as ProductType};
  if(host.includes("target.")) return {merchant:"Target",network:"Impact",productType:"dropshipping" as ProductType};
  if(host.includes("mavely")||u.searchParams.has("mavely")) return {merchant:"Mavely",network:"Mavely",productType:"dropshipping" as ProductType};
  if(host.includes("etsy.")) return {merchant:"Etsy",network:"Awin",productType:"dropshipping" as ProductType};
  if(host.includes("ebay.")) return {merchant:"eBay",network:"eBay Partner Network",productType:"dropshipping" as ProductType};
  const merchant=host.split(".")[0].replace(/[-_]/g," ").replace(/\b\w/g,c=>c.toUpperCase());
  return {merchant,network:"",productType:"dropshipping" as ProductType};
 }catch{return {merchant:"",network:"",productType:"dropshipping" as ProductType}}
}
